steps.run:
set -euo pipefail
mkdir "$RUNNER_TEMP/compatibility-unused-tools"
tools="$RUNNER_TEMP/compatibility-unused-tools"
args=()
case "$CELL" in
  c|rust|go|go-queues) ;;
  java) tools="$RUNNER_TEMP/wasi-sdk-29.0-x86_64-linux"; args+=(--read-only-cache "$RUNNER_TEMP/compatibility-java-prerequisite/compiler/gradle-home/caches/modules-2") ;;
  dotnet) tools="$RUNNER_TEMP/compatibility-dotnet-tools" ;;
  typescript) tools="$RUNNER_TEMP/compatibility-typescript-tools"; args+=(--engine "$RUNNER_TEMP/compatibility-typescript-engine/products") ;;
  typescript-initializer) tools="$RUNNER_TEMP/compatibility-typescript-tools" ;;
  *) exit 2 ;;
esac
python3 -B tools/qualify_compatibility_closure.py --cell "$CELL" --native "$RUNNER_TEMP/compatibility-native" --tools "$tools" --output "$RUNNER_TEMP/compatibility-result" --go-selected-body-only "${args[@]}"
